#include <immintrin.h>

// strided access: prefetch the next row outside the hot arithmetic
for (std::size_t i = 0; i < rows; i++) {
    const auto *cur = &a[i * cols];
    const auto *nxt = &a[std::min(i + 4, rows - 1) * cols];   // a few rows ahead
    for (std::size_t c = 0; c < cols; c++) {
        __builtin_prefetch(&nxt[c], 0, 2);       // outside the inner loop: keeps vectorisation
        sum += cur[c] * w[c];                     // inner loop stays vectorisable
    }
}

